import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"昭世","description":"","frontmatter":{"title":"昭世","date":"2026-11-24T00:00:00.000Z","seq":42,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王褒","source_book":"楚辞","prev":{"text":"危俊","link":"/blogs/楚辞/危俊.html"},"next":{"text":"尊嘉","link":"/blogs/楚辞/尊嘉.html"}},"headers":[],"relativePath":"blogs/楚辞/昭世.md","filePath":"blogs/楚辞/昭世.md"}'),o={name:"blogs/楚辞/昭世.md"};function l(n,a,c,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="昭世" tabindex="-1">昭世 <a class="header-anchor" href="#昭世" aria-label="Permalink to &quot;昭世&quot;">​</a></h1><p class="poem-meta">先秦 · 王褒　·　九怀</p><div class="poem"><p class="poem-stanza">世溷兮冥昏，违君兮归真。</p><p class="poem-stanza">乘龙兮偃蹇，高回翔兮上臻。</p><p class="poem-stanza">袭英衣兮缇[糹習]，披华裳兮芳芬。</p><p class="poem-stanza">登羊角兮扶舆，浮云漠兮自娱。</p><p class="poem-stanza">握神精兮雍容，与神人兮相胥。</p><p class="poem-stanza">流星坠兮成雨，进瞵盼兮上丘墟。</p><p class="poem-stanza">览旧邦兮滃郁，余安能兮久居。</p><p class="poem-stanza">志怀逝兮心懰栗，纡余辔兮踌躇。</p><p class="poem-stanza">闻素女兮微歌，听王后兮吹竽。</p><p class="poem-stanza">魂悽怆兮感哀，肠回回兮盘纡。</p><p class="poem-stanza">抚余佩兮缤纷，高太息兮自怜。</p><p class="poem-stanza">使祝融兮先行，令昭明兮开门。</p><p class="poem-stanza">驰六蛟兮上征，竦余驾兮入冥。</p><p class="poem-stanza">历九州兮索合，谁可与兮终生。</p><p class="poem-stanza">忽反顾兮西囿，睹轸丘兮崎倾。</p><p class="poem-stanza">横垂涕兮泫流，悲余后兮失灵。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
